    (r"\b(đại sài gòn phía đại đồng nai truyền hình a sở tri ân có rồi thì đọc tôi nghe giải đặc biệt khen)\b", "Đài Sài Gòn với đài Đồng Nai chiều nay xổ chưa em, có rồi thì đọc tôi nghe giải đặc biệt hen"),
    (r"\b(tem giúp em tuần này nhà mình ép coi nhiều số điện nhé rồi cài cho đèn biển hiệu tự thắt lúc mười giờ tới tên quy tắc thì để đúng số điện tuần này càng chữ ki lô oát giờ là được song lưu (?:vi trú|ghi chú) luôn dẫn giảm tới cát tối nội dung là tắt biển hiệu khi mất điện chạm ngưỡng)\b", "xem giúp em tuần này nhà mình hết bao nhiêu số điện nhé, rồi cài cho đèn biển hiệu tự tắt lúc 10 giờ tối, tên quy tắc thì để đúng số điện tuần này kèm chữ ki-lô-oát giờ là được, xong lưu ghi chú Hướng dẫn giảm tải ca tối, nội dung là tắt biển hiệu khi mức điện chạm ngưỡng"),
    (r"\b(cứ ở đặt bên cô ba hai tô bún bò đặc biệt với nhà mèo hai ly trái đào chăn xé)\b", "rứa đặt bên Cô Ba hai tô bún bò đặc biệt, với Nhà Mèo hai ly trà đào cam sả"),
    (r"\b(à và tự trả tiền mẹ nha còn cây hép thứ bảy tuần sau)\b", "à bật tự trả tiền mạng nha, còn cái hạn thứ bảy tuần sau"),
    (r"\b(sửa chụp ảnh kịch chú tướng vàng vừa lưu)\b", "sửa giúp anh ghi chú tiệm vàng vừa lưu"),
    (r"\b(cơ lệnh hướt có cửa nào rút giờ xe rút không có thì đánh ga lô hành sáng bay gọi nhắc tôi nghen)\b", "coi lịch thuốc, có cữ nào trước giờ xe rước hông, có thì nhắn Zalo Hằng sáng mai gọi nhắc tôi nghen"),
    (r"\b(cái camera phần kia bảo mày kẹt nổi lắm giờ còn chờ ghi hình thì bớt chân ở đấy vãn vừa nghe)\b", "cái camera hôm kia báo mất kết nối á, giờ vẫn chưa ghi hình thì bật chế độ đi vắng giùm nghe"),
    (r"\b(không mưa thì huệ huệ thật luôn cho em nhé)\b", "không, mưa thì hủy buổi tập luôn cho em nhé"),
